// Fonction pour obtenir une traduction
export const getMenuText = (lang, path) => {
  const keys = path.split('.');
  let value = menuTranslations[lang] || menuTranslations.fr;
  
  for (const key of keys) {
    value = value?.[key];
    if (!value) return path;
  }
  
  return value;
};
